const root = $env.REDANVIL_REPO;
if (!root) {
  throw new Error('REDANVIL_REPO is not set; the error workflow cannot write an alert');
}
const execution = $json.execution || {};
const workflowInfo = $json.workflow || {};
const failure = execution.error || {};
const message = typeof failure.message === 'string' && failure.message
  ? failure.message
  : 'build workflow failed';
const payload = {
  executionId: String(execution.id ?? 'unknown'),
  source: 'n8n:' + String(workflowInfo.id || "redanvilFull001"),
  message,
  ref: typeof execution.url === 'string' ? execution.url : null
};
const b64 = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');
const script = JSON.stringify(String(root).replaceAll('\\', '/') + '/n8n-prototype/dispatch/write-alert.mjs');
const cmd = 'node ' + script + ' --payloadB64=' + b64 + ' --repoRoot=' + JSON.stringify(String(root));
return [{ json: { cmd } }];
